You are a formal verification assistant. The following Dafny program fails Dafny verification.

=== PROGRAM ===
function sorted(a: array<int>) : bool
    reads a
{
   forall i,j : int :: 0 <= i < j < a.Length ==> a[i] <= a[j]
}

method BinarySearch(a: array<int>, x: int) returns (index: int)
    requires sorted(a)
    ensures 0 <= index < a.Length ==> a[index] == x
    ensures index == -1 ==> forall i : int :: 0 <= i < a.Length ==> a[i] != x
{
    var low := 0;
    var high := a.Length - 1;
    var mid := 0;

    while (low <= high) 
        invariant 0 <= low <= high + 1 <= (a.Length) + 1
        invariant x !in a[..low] && x !in a[high + 1..]
    {
        mid := (high + low) / 2;
        if a[mid] < x {
            low := mid + 1;
        }
        else if a[mid] > x {
            high := mid - 1;
        }
        else {
            return mid;
        }
    }
    return -1;
}

=== DAFNY ERROR ===
program.dfy(19,25): Error: upper bound below lower bound or above length of array

program.dfy(19,43): Error: lower bound out of range

program.dfy(22,12): Error: index out of range

